import {sortingView,startSorting,setSortingProgram,chooseSortingParcel,setSortingPrediction,stepSorting,restartSortingTrace,supportSorting,keepSortingRun,sortingOutcome,sortingBasketLabel} from './sorting-desk-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,attr,kind='secondary')=>`<button type="button" class="${kind}" ${attr}>${label}</button>`;
const conditionLabels={'stamp-star':'stamp is star','stamp-circle':'stamp is circle','wrap-blue':'wrap is blue','wrap-yellow':'wrap is yellow'};
const sourceJson=x=>{try{return JSON.stringify(x,null,2);}catch{return 'This record could not be displayed. Keep the original download.';}};
const badge=(source,id)=>esc(sortingBasketLabel(source,id));
function cardArt(parcel){
 const star=parcel.stamp==='star';
 const shape=star?'<path d="M60 16 68 33 87 36 73 49 76 68 60 59 44 68 47 49 33 36 52 33Z" fill="#f7d271" stroke="#183f39" stroke-width="2"/>':'<circle cx="60" cy="43" r="22" fill="#f7d271" stroke="#183f39" stroke-width="2"/>';
 return `<svg class="sorting-parcel-art" viewBox="0 0 120 94" role="img" aria-label="${esc(parcel.stamp)} stamp; ${esc(parcel.wrap)} wrap"><rect x="7" y="8" width="106" height="78" rx="10" fill="${parcel.wrap==='blue'?'#bad7e4':'#f6df97'}" stroke="#183f39" stroke-width="3"/><path d="M19 14 40 80M45 14 66 80M71 14 92 80" stroke="${parcel.wrap==='blue'?'#729ab5':'#c69a52'}" stroke-width="3" opacity=".65"/>${shape}</svg>`;
}
function programSelect(r,part,label,options){
 const selected=r.program[part];return `<label class="sorting-field">${label}<select data-sorting-program="${part}"><option value=""${selected===null?' selected':''}>${part==='condition'?'Choose a condition':'Choose a basket'}</option>${options.map(([value,name])=>`<option value="${esc(value)}"${selected===value?' selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
}
function ruleSentence(r){const p=r.program,s=r.source;return `If ${p.condition?conditionLabels[p.condition]:'Choose a condition'}, put it in ${p.then?sortingBasketLabel(s,p.then):'Choose a basket'}; otherwise put it in ${p.else?sortingBasketLabel(s,p.else):'Choose a basket'}.`;}
function trace(r,v){
 if(r.phase==='ready')return '<p id="sorting-trace" tabindex="-1">The machine is waiting. Choose a full rule, then step it.</p>';
 const result=sortingOutcome(r.source,r.program,r.selectedParcel);if(!result)return '<p id="sorting-trace" tabindex="-1">This trace cannot be read here. Earlier work remains in your notes.</p>';
 const condition=`The ${result.input} is ${result.observed}. Is ${conditionLabels[r.program.condition]}? ${result.yes?'Yes':'No'}. ${result.yes?'Then':'Otherwise'} runs. ${esc(r.source.text.otherBranch)}`;
 if(r.phase==='condition')return `<p id="sorting-trace" tabindex="-1">${esc(condition)}</p><p class="sorting-branch">Taken branch: ${result.branch==='then'?'Then':'Otherwise'}. The other branch is not taken.</p>`;
 if(!v.resultAvailable)return '<p id="sorting-trace" tabindex="-1">An earlier result cannot be displayed here. Its raw check remains in notes. Start this trace again to continue.</p>';
 return `<div id="sorting-trace" class="sorting-result" tabindex="-1"><p>${esc(condition)}</p><p>Your rule sent this parcel to <strong>${badge(r.source,result.actual)}</strong>. Pip's request calls for <strong>${badge(r.source,result.requested)}</strong>.</p><p>${esc(result.matches?r.source.text.fit:r.source.text.mismatch)}</p></div>`;
}
function runHistory(v){const r=v.root;return `<details class="sorting-history"><summary>Latest twelve runs (${v.readable.length})${v.unreadable.length?`; ${v.unreadable.length} unreadable`:''}</summary>${v.kept?`<section class="sorting-kept"><h3>Kept run</h3><p>${esc(v.kept.source.parcels.find(p=>p.id===v.kept.check.parcelId)?.title||v.kept.check.parcelId)}. Rule sent it to ${badge(v.kept.source,v.kept.check.actual)}; Pip's request called for ${badge(v.kept.source,v.kept.check.requested)}.</p></section>`:''}${v.keptUnreadable?'<p>A kept run is unreadable here; its raw copy remains in notes.</p>':''}${v.readable.map(({check:c})=>`<article><h3>Run ${c.id}: ${esc(r.source.parcels.find(p=>p.id===c.parcelId)?.title||c.parcelId)}</h3><p>${esc(conditionLabels[c.program.condition])}: ${c.yes?'Yes':'No'}. ${c.branch==='then'?'Then':'Otherwise'} sent it to ${badge(r.source,c.actual)}. Pip requested ${badge(r.source,c.requested)}. ${c.matches?'Same basket.':'Different baskets.'}</p><p>Prediction before stepping: ${c.prediction==='unsure'?'not sure':c.prediction?badge(r.source,c.prediction):'none'}. Help opened: ${c.support.helpOpened?'yes':'no'}. Together: ${c.support.together?'reported':'not reported'}.</p></article>`).join('')}${v.unreadable.length?`<p>${v.unreadable.length} earlier checks are unreadable; they remain in your notes.</p>`:''}${!v.readable.length&&!v.unreadable.length&&!r.kept?'<p>No run has been saved yet.</p>':''}</details>`;}
const confirmDialog='<dialog class="sorting-confirm"><div class="dialog-content"><h2>Start a separate desk?</h2><p>The whole earlier desk, including its checks and any earlier recovery, will stay in your notes. Download notes first if you want a separate copy.</p><div class="sorting-actions"><button type="button" class="secondary" data-sorting-cancel>Keep this desk</button><button type="button" class="primary" data-sorting-confirm>Keep earlier desk and start</button></div></div></dialog>';
export function sortingEntry(){return '<section class="sorting-entry"><h2>Willow Sorting Desk</h2><p>Set one if/otherwise rule, then see where four made-up parcels go.</p><a class="secondary" href="#post/sorting">Try the Willow Sorting Desk</a></section>';}
export function sortingPage(state){
 const v=sortingView(state),head='<section class="sorting-desk" data-sorting-root><header><a class="back" href="#post">Back to Willow Post Office</a><p class="sorting-eyebrow">A tabletop rule machine</p><h1>Willow Sorting Desk</h1></header>';
 if(v.status==='missing')return `${head}<p>Make one if/otherwise rule and test four made-up parcels. Your deliveries stay waiting in the Post Office.</p>${btn('Start a desk','data-sorting-start','primary')}<p id="sorting-status" role="status" tabindex="-1"></p></section>`;
 if(v.status==='recovery')return `${head}<h2>An earlier desk is kept</h2><p>This saved desk cannot be opened here. Its entire original record stays in Grown-up notes and the download.</p><p><a href="#notes">Grown-up notes and download</a></p>${btn('Start a separate desk','data-sorting-new')}<p id="sorting-status" role="status" tabindex="-1"></p>${confirmDialog}</section>`;
 const r=v.root,parcel=r.source.parcels.find(p=>p.id===r.selectedParcel),complete=!!(r.program.condition&&r.program.then&&r.program.else),result=r.phase==='result'&&v.resultAvailable,hasContrast=r.source.parcels.some(p=>p.id!==parcel.id&&p.stamp===parcel.stamp&&p.wrap!==parcel.wrap);
 const basketOptions=r.source.baskets.map(b=>[b.id,b.label]);
 return `${head}<p>${esc(r.source.text.intro)}</p><p class="sorting-request">${esc(r.source.request)}</p><div class="sorting-layout"><section class="sorting-cards"><h2>Choose a parcel</h2><div class="sorting-card-list">${r.source.parcels.map(p=>`<button type="button" data-sorting-parcel="${esc(p.id)}" aria-pressed="${p.id===r.selectedParcel}" class="sorting-card ${p.id===r.selectedParcel?'selected':''}">${cardArt(p)}<span>${esc(p.title)}</span></button>`).join('')}</div>${r.source.parcels.some(p=>p.id==='star-yellow')?btn('Try a contrasting parcel','data-sorting-contrast'):''}<h3 id="sorting-card-title" tabindex="-1">${esc(parcel.title)}</h3><p>${esc(parcel.stamp)} stamp; ${esc(parcel.wrap)} wrap.</p></section><section class="sorting-rule"><h2>Set your rule</h2><div class="sorting-fields">${programSelect(r,'condition','Condition',Object.entries(conditionLabels))}${programSelect(r,'then','Then basket',basketOptions)}${programSelect(r,'else','Otherwise basket',basketOptions)}</div><p id="sorting-rule-sentence" tabindex="-1">${esc(ruleSentence(r))}</p><p>The machine follows the rule you set. Pip's request is a separate intention.</p></section></div><section class="sorting-trace-panel"><h2>Step the machine</h2>${r.phase==='ready'&&complete?`<fieldset class="sorting-prediction"><legend>${esc(r.source.text.predictionPrompt)}</legend><div class="sorting-actions">${r.source.baskets.map(b=>btn(esc(b.label),`data-sorting-predict="${esc(b.id)}" aria-pressed="${r.prediction===b.id}"`)).join('')}${btn('I am not sure yet',`data-sorting-predict="unsure" aria-pressed="${r.prediction==='unsure'}"`)}${btn('Leave it blank','data-sorting-predict=""')}</div></fieldset>`:''}${trace(r,v)}<div class="sorting-actions">${r.phase==='ready'?btn('Test the condition',`data-sorting-step ${complete?'':'disabled'}`,'primary'):r.phase==='condition'?btn('Take the branch','data-sorting-step','primary'):''}${r.phase!=='ready'?btn('Start this trace again','data-sorting-restart'):''}${result?btn('Keep this run','data-sorting-keep'):''}</div><p class="sorting-window-note">Latest twelve readable runs stay here. Before a new run replaces the oldest readable one, keep it or download notes if you want that copy. Unreadable records are never removed by a new run.</p>${result&&hasContrast?`<p>${esc(r.source.text.counterexample)}</p>`:''}<details class="sorting-help" ${r.support.helpOpened||r.support.together?'open':''}><summary>Help if you like</summary>${btn('Show an explanation','data-sorting-help')}${r.support.helpOpened?`<p id="sorting-help-text" tabindex="-1">${esc(r.source.text.help)}</p>`:''}${btn('We worked together',`data-sorting-together aria-pressed="${r.support.together}"`)}${hearButton(`${r.source.request} ${ruleSentence(r)}`,'Hear this rule')}</details></section>${runHistory(v)}<details class="sorting-parent"><summary>For grown-ups</summary><p>These are pictured, supplied rule checks. Predictions are optional and recorded before the condition is shown. A fitting route does not establish independent coding or mastery.</p>${btn('Start a separate desk','data-sorting-new')}</details><p><a href="#notes">Grown-up notes and download</a></p><p id="sorting-status" role="status" tabindex="-1"></p>${confirmDialog}</section>`;
}
export function sortingNotes(state){if(!Object.hasOwn(state,'sortingDesk'))return '';const v=sortingView(state);return `<details class="panel"><summary>Willow Sorting Desk: supplied rule practice</summary><p>${v.status==='recovery'?'This desk cannot be opened here. Its original record remains below.':`Latest ${v.readable.length} readable runs. ${v.unreadable.length} unreadable checks remain raw. ${v.kept?'One run explicitly kept.':v.keptUnreadable?'A kept run is unreadable but preserved.':'No run explicitly kept.'}`} A fitting route is not independent coding or mastery.</p><pre>${esc(sourceJson(state.sortingDesk))}</pre></details>`;}
export function bindSorting(state,{save,render,focus,canExport}={}){
 const root=document.querySelector('[data-sorting-root]');if(!root)return;
 const refuse='This action could not fit safely in your downloadable notes. Earlier work is unchanged. Download notes first or use a separate explorer.';
 const status=message=>{const n=document.querySelector('#sorting-status');if(n){n.textContent=message;focus?.('#sorting-status');}};
 const refresh=target=>{save?.();render?.();focus?.(target);};
 root.querySelector('[data-sorting-start]')?.addEventListener('click',()=>startSorting(state,canExport)?refresh('#sorting-card-title'):status(refuse));
 root.querySelectorAll('[data-sorting-program]').forEach(el=>el.addEventListener('change',()=>setSortingProgram(state,el.dataset.sortingProgram,el.value||null)?refresh('#sorting-rule-sentence'):status('That rule choice could not be saved.')));
 root.querySelectorAll('[data-sorting-parcel]').forEach(el=>el.addEventListener('click',()=>chooseSortingParcel(state,el.dataset.sortingParcel)?refresh('#sorting-card-title'):null));
 root.querySelector('[data-sorting-contrast]')?.addEventListener('click',()=>chooseSortingParcel(state,'star-yellow')&&refresh('#sorting-card-title'));
 root.querySelectorAll('[data-sorting-predict]').forEach(el=>el.addEventListener('click',()=>setSortingPrediction(state,el.dataset.sortingPredict||null)&&refresh('#sorting-trace')));
 root.querySelector('[data-sorting-step]')?.addEventListener('click',()=>stepSorting(state,canExport)?refresh('#sorting-trace'):status(refuse));
 root.querySelector('[data-sorting-restart]')?.addEventListener('click',()=>restartSortingTrace(state)&&refresh('#sorting-trace'));
 root.querySelector('[data-sorting-keep]')?.addEventListener('click',()=>{if(!keepSortingRun(state,canExport)){status(refuse);return;}save?.();render?.();const history=document.querySelector('.sorting-history');if(history)history.open=true;status('This run is kept. Later runs and rule changes will leave its copy unchanged.');});
 root.querySelector('[data-sorting-help]')?.addEventListener('click',()=>supportSorting(state,'helpOpened')&&refresh('#sorting-help-text'));
 root.querySelector('[data-sorting-together]')?.addEventListener('click',()=>supportSorting(state,'together')&&refresh('[data-sorting-together]'));
 root.querySelectorAll('[data-speak]').forEach(el=>el.addEventListener('click',()=>{if(supportSorting(state,'narrationRequested'))save?.();},{capture:true}));
 const dialog=root.querySelector('.sorting-confirm');root.querySelector('[data-sorting-new]')?.addEventListener('click',()=>dialog?.showModal());
 dialog?.querySelector('[data-sorting-cancel]')?.addEventListener('click',()=>dialog.close());
 dialog?.querySelector('[data-sorting-confirm]')?.addEventListener('click',()=>{dialog.close();startSorting(state,canExport,true)?refresh('#sorting-card-title'):status(refuse);});
}
